rule "nas extract category"
when
  has_field("message")
then
  let msg = to_string($message.message);
  let m = regex("^nas\\s+([A-Za-z][A-Za-z0-9_ ]*?):\\s*(.*)$", msg);
  set_field("nas_category", to_string(m["0"]));
  set_field("nas_detail", to_string(m["1"]));
end

rule "nas connection event extract"
when
  has_field("nas_category") &&
  to_string($message.nas_category) == "Connection"
then
  let body = to_string($message.nas_detail);
  let u = regex("User\\s+\\[([^\\]]+)\\]\\s+from\\s+\\[([^\\]]+)\\]\\s+(signed\\s+in|signed\\s+out|failed\\s+to\\s+sign\\s+in|tried\\s+to\\s+sign\\s+in)\\s+to\\s+\\[([^\\]]+)\\](?:\\s+(\\w+))?(?:\\s+via\\s+\\[([^\\]]+)\\])?", body);
  set_field("nas_user",        to_string(u["0"]));
  set_field("nas_client_ip",   to_string(u["1"]));
  set_field("nas_action",      to_string(u["2"]));
  set_field("nas_target",      to_string(u["3"]));
  set_field("nas_result",      to_string(u["4"]));
  set_field("nas_auth_method", to_string(u["5"]));
end

rule "nas afp event extract"
when
  has_field("nas_category") &&
  to_string($message.nas_category) == "MacFileService Event"
then
  let body = to_string($message.nas_detail);
  let p = regex("^([A-Za-z0-9_]+),\\s+Path:\\s+([^,]+),\\s+File/Folder:\\s+(File|Folder)(?:,\\s+Size:\\s+([0-9]+)\\s*\\w*)?,?\\s*User:\\s+(\\S+),\\s+IP:\\s+([0-9.]+)", body);
  set_field("nas_afp_op",     to_string(p["0"]));
  set_field("nas_path",       to_string(p["1"]));
  set_field("nas_file_kind",  to_string(p["2"]));
  set_field("nas_size_bytes", to_string(p["3"]));
  set_field("nas_user",       to_string(p["4"]));
  set_field("nas_client_ip",  to_string(p["5"]));
end
